+// The audit trail: one entry per request that changes data, never edited.
+
+/** Appends an audit entry (the caller supplies `at`, an ISO instant). */
+export function recordAudit(store, { at, keyName, method, path, status }) {
+  store.data.audit.push({ at, keyName, method, path, status });
+}
+
+/** All audit entries, newest first. */
+export function listAudit(store) {
+  return [...store.data.audit].reverse();
+}
