+// Authentication and roles for the HTTP layer. Keys live in the data as
+// apiKeys: [{ key, name, role }]; requests send `Authorization: Bearer <key>`.
+import { AppError } from "../errors.js";
+
+/** Roles from least to most powerful. */
+export const ROLES = Object.freeze(["viewer", "cook", "manager"]);
+
+// What a cook may do besides reading: [method, path pattern].
+const COOK_ROUTES = [
+  ["POST", /^\/recipes\/[^/]+\/cook$/],
+  ["POST", /^\/batches\/[^/]+\/waste$/],
+  ["POST", /^\/temperatures$/],
+  ["POST", /^\/stocktakes\/[^/]+\/counts$/],
+];
+
+/** The API key record sent in the request headers, or throws `unauthorized`. */
+export function authenticate(store, headers) {
+  const name = Object.keys(headers).find((h) => h.toLowerCase() === "authorization");
+  const m = /^Bearer\s+(\S+)$/.exec(String(name ? headers[name] : ""));
+  const found = m && (store.data.apiKeys ?? []).find((k) => k.key === m[1]);
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** Throws `forbidden` unless `role` may call `method` on `path`. */
+export function authorize(role, method, path) {
+  if (role === "manager") return;
+  if (path === "/audit") throw new AppError("forbidden");
+  if (method === "GET") return;
+  if (role === "cook" && COOK_ROUTES.some(([m, re]) => m === method && re.test(path))) return;
+  throw new AppError("forbidden");
+}
